import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxpool3d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <limits>

__global__ void maxpool3d_kernel(const float* input, float* output, 
                                 int batchSize, int channels, 
                                 int inputD, int inputH, int inputW, 
                                 int outputD, int outputH, int outputW,
                                 int kernelD, int kernelH, int kernelW,
                                 int strideD, int strideH, int strideW,
                                 int padD, int padH, int padW,
                                 int dilationD, int dilationH, int dilationW) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batchSize * channels * outputD * outputH * outputW) {
        return;
    }

    int w_out = idx % outputW;
    int h_out = (idx / outputW) % outputH;
    int d_out = (idx / (outputW * outputH)) % outputD;
    int c = (idx / (outputW * outputH * outputD)) % channels;
    int n = idx / (outputW * outputH * outputD * channels);

    int d_in_start = d_out * strideD - padD;
    int h_in_start = h_out * strideH - padH;
    int w_in_start = w_out * strideW - padW;

    float max_val = -FLT_MAX;
    for (int kd = 0; kd < kernelD; ++kd) {
        int d_in = d_in_start + kd * dilationD;
        if (d_in < 0 || d_in >= inputD) continue;
        for (int kh = 0; kh < kernelH; ++kh) {
            int h_in = h_in_start + kh * dilationH;
            if (h_in < 0 || h_in >= inputH) continue;
            for (int kw = 0; kw < kernelW; ++kw) {
                int w_in = w_in_start + kw * dilationW;
                if (w_in < 0 || w_in >= inputW) continue;

                int index_in = (((n * channels + c) * inputD + d_in) 
                                * inputH + h_in) * inputW + w_in;
                float val = input[index_in];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
    }
    int index_out = (((n * channels + c) * outputD + d_out) 
                     * outputH + h_out) * outputW + w_out;
    output[index_out] = max_val;
}

torch::Tensor maxpool3d_forward_cuda(torch::Tensor input, 
                                     int kernelD, int kernelH, int kernelW,
                                     int strideD, int strideH, int strideW,
                                     int padD, int padH, int padW,
                                     int dilationD, int dilationH, int dilationW) {
    int batchSize = input.size(0);
    int channels = input.size(1);
    int inputD = input.size(2);
    int inputH = input.size(3);
    int inputW = input.size(4);

    int outputD = (inputD + 2 * padD - dilationD * (kernelD - 1) - 1) / strideD + 1;
    int outputH = (inputH + 2 * padH - dilationH * (kernelH - 1) - 1) / strideH + 1;
    int outputW = (inputW + 2 * padW - dilationW * (kernelW - 1) - 1) / strideW + 1;

    auto options = input.options().dtype(torch::kFloat32);
    auto output = torch::empty({batchSize, channels, outputD, outputH, outputW}, options);

    int total = batchSize * channels * outputD * outputH * outputW;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    maxpool3d_kernel<<<gridSize, blockSize>>>(
        input.data_ptr<float>(), output.data_ptr<float>(),
        batchSize, channels, inputD, inputH, inputW,
        outputD, outputH, outputW,
        kernelD, kernelH, kernelW,
        strideD, strideH, strideW,
        padD, padH, padW,
        dilationD, dilationH, dilationW
    );

    return output;
}
"""

maxpool3d_cpp_source = r"""
torch::Tensor maxpool3d_forward_cuda(torch::Tensor input, 
                                     int kernelD, int kernelH, int kernelW,
                                     int strideD, int strideH, int strideW,
                                     int padD, int padH, int padW,
                                     int dilationD, int dilationH, int dilationW);
"""

maxpool3d = load_inline(
    name="maxpool3d",
    cpp_sources=maxpool3d_cpp_source,
    cuda_sources=maxpool3d_source,
    functions=["maxpool3d_forward_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0, dilation: int = 1, return_indices: bool = False, ceil_mode: bool = False):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        # return_indices and ceil_mode are not implemented in this custom kernel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool3d.maxpool3d_forward_cuda(
            x,
            self.kernel_size, self.kernel_size, self.kernel_size,
            self.stride, self.stride, self.stride,
            self.padding, self.padding, self.padding,
            self.dilation, self.dilation, self.dilation
        )
